import pytest


def config_value(text: str, key: str) -> str:
    """Return the value for `key` in `name=value` config text, or "" if absent.

    The text is split into lines (any line ending, including "\\r\\n").
    Each line is split at its first "=", so values may themselves contain "=".
    Whitespace around the name and around the value is stripped.

    Lines that are blank, start with "#" (after stripping), or have no "="
    are ignored. Key matching is exact and case-sensitive. If the key appears
    more than once, the first occurrence wins. A key present with nothing
    after the "=" yields "", the same as an absent key.
    """
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, value = line.partition("=")
        if not sep:
            continue
        if name.strip() == key:
            return value.strip()
    return ""


def test_basic_lookup() -> None:
    assert config_value("a=1\nb=2\nc=3", "b") == "2"


def test_absent_key_returns_empty_string() -> None:
    assert config_value("a=1\nb=2", "z") == ""


def test_empty_text() -> None:
    assert config_value("", "a") == ""


def test_whitespace_stripped_around_name_and_value() -> None:
    assert config_value("  name  =  hello world  \n", "name") == "hello world"


def test_value_may_contain_equals() -> None:
    assert config_value("url=http://x/?q=1&r=2", "url") == "http://x/?q=1&r=2"


def test_empty_value() -> None:
    assert config_value("a=\nb=2", "a") == ""


def test_comment_lines_ignored() -> None:
    text = "# a=1\n  # a=2\na=3"
    assert config_value(text, "a") == "3"


def test_comment_only_text_has_no_keys() -> None:
    assert config_value("#a=1", "a") == ""
    assert config_value("#a=1", "#a") == ""


def test_blank_and_malformed_lines_ignored() -> None:
    text = "\n   \nnot a pair\nkey=val\n"
    assert config_value(text, "key") == "val"
    assert config_value(text, "not a pair") == ""


def test_first_occurrence_wins() -> None:
    assert config_value("a=1\na=2", "a") == "1"


def test_key_match_is_exact_and_case_sensitive() -> None:
    text = "Name=upper\nnamesake=other\nname=lower"
    assert config_value(text, "name") == "lower"
    assert config_value(text, "Name") == "upper"
    assert config_value(text, "nam") == ""


def test_crlf_line_endings() -> None:
    assert config_value("a=1\r\nb=2\r\n", "b") == "2"


@pytest.mark.parametrize(
    ("text", "key", "expected"),
    [
        ("a=1", "a", "1"),
        ("a = 1", "a", "1"),
        ("\ta\t=\t1\t", "a", "1"),
        ("x=1\ny=2", "y", "2"),
        ("x=1", "y", ""),
    ],
)
def test_parametrized_lookup(text: str, key: str, expected: str) -> None:
    assert config_value(text, key) == expected
